import{az as e,P as l,Q as i,aQ as r}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const b=JSON.parse('{"title":"概念","description":"","frontmatter":{},"headers":[],"relativePath":"AI/index.md","filePath":"AI/index.md","lastUpdated":1774793456000}'),n={name:"AI/index.md"};function t(o,a,h,d,s,c){return l(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="概念" tabindex="-1">概念 <a class="header-anchor" href="#概念" aria-label="Permalink to “概念”">​</a></h1><p>它们不是彼此取代的关系，而是一起构成了AI自动化协作的完整体系</p><h2 id="让ai给你写" tabindex="-1">让AI给你写 <a class="header-anchor" href="#让ai给你写" aria-label="Permalink to “让AI给你写”">​</a></h2><p>别看以下名词那么多，其实理解了其中的意思， 你想做什么直接让AI给你写，给你写一个Agent、MCP都是可以的，最主要的是你知道它能做什么和你想要什么</p><h2 id="名词" tabindex="-1">名词 <a class="header-anchor" href="#名词" aria-label="Permalink to “名词”">​</a></h2><p>Vibe Coding</p><h2 id="关键词" tabindex="-1">关键词 <a class="header-anchor" href="#关键词" aria-label="Permalink to “关键词”">​</a></h2><ul><li>LLM - Large Language Model 大语言模型</li><li>Prompt 提示词</li><li>System Prompt 系统提示词</li><li>User Prompt 用户提示词</li><li>Memory 记忆</li><li>web search 网络搜索</li><li>RAG 检索增强生成</li><li>AI Agent</li><li>Agent Tools 定义工具，可以读取、修改本地文件等操作</li><li>Function Calling 约定数据格式</li><li>MCP 约定调用工具格式</li><li>Skill 技能（自定义技能）</li></ul><h2 id="user-prompt-用户提示词" tabindex="-1">User Prompt 用户提示词 <a class="header-anchor" href="#user-prompt-用户提示词" aria-label="Permalink to “User Prompt 用户提示词”">​</a></h2><p>用户所输入的内容，白话就是将输入的内容进行提示词拆解。</p><h2 id="system-prompt-系统提示词" tabindex="-1">System Prompt 系统提示词 <a class="header-anchor" href="#system-prompt-系统提示词" aria-label="Permalink to “System Prompt 系统提示词”">​</a></h2><p>使用自然语言来描述角色、性格、背景知识、语气，(这些描述不是出自用户之口，而是用于附带)，为用户提供一套沟通环境，通过系统提示词让AI变得更专业（更生动）</p><h2 id="memory" tabindex="-1">Memory <a class="header-anchor" href="#memory" aria-label="Permalink to “Memory”">​</a></h2><p>单次对话，一问一答，不能进行追问。 所以每次沟通都要把之前的对话也携带过去，生成上下文对话。</p><h2 id="ai-agent" tabindex="-1">AI Agent <a class="header-anchor" href="#ai-agent" aria-label="Permalink to “AI Agent”">​</a></h2><p>本质大语言模型只能回复消息，并不能读取文件、修改文件。而Agent让一个聊天机器人变成一个真正可以有能力动起来的机器人，通过你下达命令让AI替你做事情</p><h2 id="web-search" tabindex="-1">web search <a class="header-anchor" href="#web-search" aria-label="Permalink to “web search”">​</a></h2><p>对话是有时效性的， 大语言模型训练完成之后又有新的及时性信息的发生，所以可以进行联网搜索最新的信息</p><h2 id="rag" tabindex="-1">RAG <a class="header-anchor" href="#rag" aria-label="Permalink to “RAG”">​</a></h2><p>检索增强生成，对于垂直领域、非开源领域（医疗、法律）缺少公开数据训练，让AI访问使用私有数据创建知识库，然后检索知识库进行回答。 我想到的有哪些：</p><ol><li>接口文档</li></ol><h2 id="function-calling" tabindex="-1">Function Calling <a class="header-anchor" href="#function-calling" aria-label="Permalink to “Function Calling”">​</a></h2><p>对系统提示词进行了标准化，转成适配各家模型的格式，例如JSON格式 让AI标准化的行为好处</p><ol><li>对自然语言的描述更加准确</li><li>准确意味着节省Token，更有效率</li></ol><h2 id="mcp" tabindex="-1">MCP <a class="header-anchor" href="#mcp" aria-label="Permalink to “MCP”">​</a></h2><p>因为各家模型的标准（格式）不一致，并不支持跨模型通用， 而且有些模型不支持<code>Function Calling</code>, 所以 <code>System Prompt</code> 和 <code>Function Calling</code> 是并存的。而 <code>MCP</code> 统一了 AI 模型与外部工具 / 数据源的连接规范，可标准化调用数据库、API、本地文件等，降低 AI 智能体（Agent）开发门槛。</p><h2 id="skill" tabindex="-1">Skill <a class="header-anchor" href="#skill" aria-label="Permalink to “Skill”">​</a></h2><p>将所有的提示词连同用户的问题发送给AI模型</p>',28)])])}const P=e(n,[["render",t]]);export{b as __pageData,P as default};
